 @Override public void onCreate(Bundle b){super.onCreate(b);auth=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();storage=FirebaseStorage.getInstance();if(auth.getCurrentUser()==null)login();else boot();}
 void login(){LinearLayout r=base();r.setGravity(Gravity.CENTER);r.setPadding(dp(24),dp(20),dp(24),dp(20));ImageView logo=new ImageView(this);logo.setImageResource(com.gigbiz.app.R.drawable.ic_gigbiz);logo.setScaleType(ImageView.ScaleType.FIT_CENTER);r.addView(logo,new LinearLayout.LayoutParams(dp(100),dp(100)));TextView h=tv("GigSathi",32,true);h.setGravity(Gravity.CENTER);r.addView(h,new LinearLayout.LayoutParams(-1,dp(60)));TextView s=tv("Earn • Work • Grow",17,false);s.setGravity(Gravity.CENTER);r.addView(s,new LinearLayout.LayoutParams(-1,dp(40)));EditText e=field("Email"),p=field("Password");p.setInputType(0x81);add(r,e,54,10);add(r,p,54,10);TextView b=button("LOGIN",purple);add(r,b,54,18);TextView n=tv("New worker? Create account",15,true);n.setGravity(Gravity.CENTER);add(r,n,45,8);TextView m=tv("Team Member Login / Register",15,true);m.setTextColor(purple);m.setGravity(Gravity.CENTER);add(r,m,48,4);b.setOnClickListener(v->{auth.signInWithEmailAndPassword(e.getText().toString().trim(),p.getText().toString()).addOnCompleteListener(x->{if(x.isSuccessful())boot();else toast(err(x.getException()));});});n.setOnClickListener(v->signup());m.setOnClickListener(v->memberAuthScreen(false));setContentView(r);}
 EditText field(String h){EditText e=new EditText(this);e.setHint(h);e.setSingleLine(true);e.setTextSize(15);e.setPadding(dp(14),0,dp(14),0);e.setBackground(stroke(Color.rgb(220,225,232),1,11));return e;}
 void signup(){LinearLayout r=base();r.setPadding(dp(22),dp(28),dp(22),dp(20));TextView h=tv("Create your GigSathi account",26,true);h.setGravity(Gravity.CENTER);add(r,h,65,0);EditText n=field("Full name"),e=field("Email"),ph=field("Mobile number"),sk=field("Skills"),loc=field("City / Location"),pw=field("Password (6+)");pw.setInputType(0x81);for(EditText x:new EditText[]{n,e,ph,sk,loc,pw})add(r,x,53,8);TextView b=button("CREATE ACCOUNT",purple);add(r,b,53,18);b.setOnClickListener(v->{auth.createUserWithEmailAndPassword(e.getText().toString().trim(),pw.getText().toString()).addOnCompleteListener(x->{if(!x.isSuccessful()){toast(err(x.getException()));return;}Map<String,Object> m=new HashMap<>();m.put("name",n.getText().toString().trim());m.put("email",e.getText().toString().trim());m.put("phone",ph.getText().toString().trim());m.put("skills",sk.getText().toString().trim());m.put("location",loc.getText().toString().trim());m.put("role","worker");m.put("wallet",0);m.put("status","active");m.put("createdAt",FieldValue.serverTimestamp());db.collection("users").document(auth.getCurrentUser().getUid()).set(m).addOnSuccessListener(z->boot()).addOnFailureListener(q->toast(err(q)));});});setContentView(r);}
 
 void memberAuthScreen(boolean unused){
  LinearLayout r=base();r.setGravity(Gravity.CENTER);r.setPadding(dp(22),dp(20),dp(22),dp(24));
  TextView h=tv("GigSathi Team Member",26,true);h.setGravity(Gravity.CENTER);add(r,h,62,0);
  TextView hint=tv("Login with the email invited by your Team Owner. New members must use the same invited email.",14,false);hint.setGravity(Gravity.CENTER);add(r,hint,75,4);
  EditText email=field("Invited email address"),pass=field("Password");pass.setInputType(0x81);add(r,email,54,8);add(r,pass,54,8);
  TextView loginBtn=button("TEAM MEMBER LOGIN",purple);add(r,loginBtn,54,16);
  TextView reg=tv("First time? Activate your team account",14,true);reg.setTextColor(purple);reg.setGravity(Gravity.CENTER);add(r,reg,48,8);
  TextView back=tv("← Back to login",14,true);back.setGravity(Gravity.CENTER);add(r,back,42,4);
  loginBtn.setOnClickListener(v->{String em=email.getText().toString().trim().toLowerCase(Locale.ROOT),pw=pass.getText().toString();if(em.isEmpty()||pw.isEmpty()){toast("Enter email and password.");return;}auth.signInWithEmailAndPassword(em,pw).addOnCompleteListener(x->{if(x.isSuccessful())boot();else toast(err(x.getException()));});});
  reg.setOnClickListener(v->memberSignupScreen());back.setOnClickListener(v->login());setContentView(r);
 }
 void memberSignupScreen(){
  LinearLayout r=base();r.setPadding(dp(20),dp(18),dp(20),dp(20));TextView h=tv("Activate Team Member Account",24,true);h.setGravity(Gravity.CENTER);add(r,h,65,0);
  EditText name=field("Full name"),email=field("Invited email (same as owner added)"),phone=field("Mobile number"),pass=field("Create password (6+ characters)");pass.setInputType(0x81);
  for(EditText e:new EditText[]{name,email,phone,pass})add(r,e,53,8);
  TextView save=button("ACTIVATE ACCOUNT",purple);add(r,save,54,18);TextView back=tv("← Back",14,true);back.setGravity(Gravity.CENTER);add(r,back,42,8);back.setOnClickListener(v->memberAuthScreen(false));
  save.setOnClickListener(v->{String n=name.getText().toString().trim(),em=email.getText().toString().trim().toLowerCase(Locale.ROOT),ph=phone.getText().toString().trim(),pw=pass.getText().toString();if(n.length()<2||!emValid(em)||ph.replaceAll("\\D","").length()<10||pw.length()<6){toast("Enter valid name, invited email, mobile and 6+ character password.");return;}
   auth.createUserWithEmailAndPassword(em,pw).addOnCompleteListener(created->{if(!created.isSuccessful()){toast(err(created.getException()));return;}String uid=auth.getCurrentUser().getUid();
    db.collection("teamMembers").whereEqualTo("email",em).get().addOnSuccessListener(invites->{if(invites.isEmpty()){auth.getCurrentUser().delete();toast("Invitation not found. Ask your Team Owner to add this email first.");return;}DocumentSnapshot invite=invites.getDocuments().get(0);String owner=invite.getString("ownerId");if(owner==null||owner.isEmpty()){auth.getCurrentUser().delete();toast("This invitation is invalid. Ask your Team Owner to add you again.");return;}
     if("active".equals(invite.getString("status"))&&invite.getString("memberUid")!=null){auth.getCurrentUser().delete();toast("This invitation has already been activated. Please log in.");return;}
     Map<String,Object> user=new HashMap<>();user.put("name",n);user.put("email",em);user.put("phone",ph);user.put("role","member");user.put("ownerId",owner);user.put("wallet",0);user.put("status","active");user.put("createdAt",FieldValue.serverTimestamp());
     db.collection("users").document(uid).set(user).addOnSuccessListener(done->db.collection("teamMembers").document(invite.getId()).update("memberUid",uid,"status","active","activatedAt",FieldValue.serverTimestamp()).addOnSuccessListener(z->boot()).addOnFailureListener(ex->{toast("Account created but invitation link update failed: "+err(ex));})).addOnFailureListener(ex->{toast("Unable to save member profile: "+err(ex));});
    }).addOnFailureListener(ex->{toast("Unable to verify invitation: "+err(ex));});
   });
  });setContentView(r);
 }
