 View bottomNavMember(){LinearLayout n=new LinearLayout(this);n.setGravity(Gravity.CENTER);n.setBackground(bg(white,16));String[] labels={"⌂\nHome","✓\nTasks","＋\nLead","₹\nWithdraw"};for(int i=0;i<labels.length;i++){final int k=i;TextView b=tv(labels[i],12,true);b.setGravity(Gravity.CENTER);b.setTextColor(purple);n.addView(b,new LinearLayout.LayoutParams(0,dp(60),1));b.setOnClickListener(v->{if(k==0)boot();else if(k==1)memberTasksScreen();else if(k==2)leadSubmitScreen(null);else withdrawScreen();});}return n;}
 void memberTasksScreen(){
  String uid=auth.getCurrentUser().getUid();LinearLayout r=base();topBar(r,"My Assigned Tasks");ScrollView s=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(14),dp(8),dp(14),dp(24));s.addView(list);r.addView(s);
  db.collection("tasks").whereEqualTo("memberId",uid).get().addOnSuccessListener(q->{if(q.isEmpty())list.addView(tv("No tasks assigned yet. Your Team Owner/Admin can assign tasks from the Admin panel.",14,false));for(DocumentSnapshot d:q){String status=d.getString("status");if(status==null)status="pending";LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(10),dp(12),dp(10));card.setBackground(stroke(Color.rgb(225,229,235),1,12));card.addView(tv(String.valueOf(d.get("title")==null?"Assigned Task":d.get("title")),17,true));card.addView(tv(String.valueOf(d.get("description")==null?"":d.get("description")),14,false));card.addView(tv("Status: "+status,13,true));if(!"completed".equals(status)){TextView done=button("MARK AS COMPLETED",green);add(card,done,44,8);String id=d.getId();done.setOnClickListener(v->db.collection("tasks").document(id).update("status","completed","completedBy",uid,"completedAt",FieldValue.serverTimestamp()).addOnSuccessListener(z->{toast("Task marked completed.");memberTasksScreen();}).addOnFailureListener(e->toast(err(e))));}list.addView(card,new LinearLayout.LayoutParams(-1,-2));}}).addOnFailureListener(e->toast(err(e)));setContentView(r);
 }
 void memberLeadsScreen(){
  String uid=auth.getCurrentUser().getUid();LinearLayout r=base();topBar(r,"My Customer Leads");ScrollView s=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(14),dp(8),dp(14),dp(24));s.addView(list);r.addView(s);
  TextView add=button("＋ SUBMIT LEAD",purple);add(list,add,50,8);add.setOnClickListener(v->leadSubmitScreen(null));
  db.collection("leads").whereEqualTo("memberId",uid).get().addOnSuccessListener(q->{if(q.isEmpty())list.addView(tv("No leads submitted yet.",14,false));for(DocumentSnapshot d:q){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(10),dp(12),dp(10));card.setBackground(stroke(Color.rgb(225,229,235),1,12));card.addView(tv(String.valueOf(d.get("customerName")==null?"Customer":d.get("customerName")),16,true));card.addView(tv(String.valueOf(d.get("gigTitle")==null?"":d.get("gigTitle")),13,false));card.addView(tv("Status: "+String.valueOf(d.get("status")==null?"pending":d.get("status")),13,true));card.addView(tv("Potential earning: ₹"+String.valueOf(d.get("taskAmount")==null?"0":d.get("taskAmount")),13,false));if(Boolean.TRUE.equals(d.getBoolean("walletCredited")))card.addView(tv("✓ Earning credited",12,true));list.addView(card,new LinearLayout.LayoutParams(-1,-2));}}).addOnFailureListener(e->toast(err(e)));setContentView(r);
 }

 void boot(){db.collection("users").document(auth.getCurrentUser().getUid()).get().addOnSuccessListener(d->{String role=d.getString("role");if("worker".equals(role))home(d);else if("member".equals(role)){if(!"active".equals(d.getString("status"))){auth.signOut();toast("Team member account is pending Admin/Team Owner approval.");login();}else memberHome(d);}else{auth.signOut();toast("Worker or Team Member account required.");login();}}).addOnFailureListener(e->toast(err(e)));}
