 double numberVal(Object o){return o instanceof Number?((Number)o).doubleValue():0.0;}
 View quickHeaderItem(String symbol,String label,int color){LinearLayout x=new LinearLayout(this);x.setOrientation(1);x.setGravity(Gravity.CENTER);TextView i=tv(symbol,23,true);i.setTextColor(color);i.setGravity(Gravity.CENTER);i.setBackground(bg(Color.rgb(242,246,252),50));x.addView(i,new LinearLayout.LayoutParams(dp(40),dp(40)));TextView t=tv(label,12,true);t.setGravity(Gravity.CENTER);x.addView(t);return x;}
 View moneyCard(String label,String value,int color,int accent,String symbol){LinearLayout x=new LinearLayout(this);x.setGravity(Gravity.CENTER_VERTICAL);x.setPadding(dp(10),dp(8),dp(8),dp(8));x.setBackground(stroke(color,1,16));LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.addView(tv(label,14,false));TextView val=tv(value,16,true);val.setTextColor(Color.BLACK);l.addView(val);x.addView(l,new LinearLayout.LayoutParams(0,-2,1));TextView icon=tv(symbol,20,true);icon.setTextColor(accent);x.addView(icon);return x;}
