 View categoryTile(String symbol,String label){LinearLayout x=new LinearLayout(this);x.setOrientation(1);x.setGravity(Gravity.CENTER);x.setPadding(dp(3),dp(8),dp(3),dp(6));x.setBackground(stroke(white,1,15));x.setElevation(dp(2));TextView i=tv(symbol,24,true);i.setTextColor(Color.rgb(35,126,223));i.setGravity(Gravity.CENTER);i.setBackground(bg(Color.rgb(220,235,255),50));LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(dp(44),dp(44));ip.bottomMargin=dp(6);x.addView(i,ip);TextView t=tv(label,12,true);t.setGravity(Gravity.CENTER);t.setMaxLines(2);x.addView(t,new LinearLayout.LayoutParams(-1,dp(36)));return x;}
