 String base="https://l86385138-pixel.github.io/app-creator-new/share.html";String title=String.valueOf(d.get("title")==null?"GigSathi Project":d.get("title"));String pay=String.valueOf(d.get("pay")==null?"0":d.get("pay"));String desc=String.valueOf(d.get("description")==null?"":d.get("description"));String url=String.valueOf(d.get("applyUrl")==null?"":d.get("applyUrl"));String image=String.valueOf(d.get("logoUrl")==null?"":d.get("logoUrl"));String leads=String.valueOf(d.get("leadCount")==null?"0":d.get("leadCount"));String sales=String.valueOf(d.get("sales")==null?"0":d.get("sales"));String workerId=auth.getCurrentUser().getUid();String workerName=auth.getCurrentUser().getDisplayName()==null?"Adviser":auth.getCurrentUser().getDisplayName();String gigId=d.getId();
