  String photo=getSharedPreferences("gigbiz_worker_photos",MODE_PRIVATE).getString(uid,"");if(!photo.isEmpty()){try{workerPhotoView.setImageURI(Uri.parse(photo));}catch(Exception ignored){workerPhotoView.setImageResource(com.gigbiz.app.R.drawable.ic_gigbiz);}}else workerPhotoView.setImageResource(com.gigbiz.app.R.drawable.ic_gigbiz);
  TextView photoBtn=button("UPLOAD ADVISER PHOTO",orange);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(42));pp.topMargin=dp(10);card.addView(photoBtn,pp);photoBtn.setOnClickListener(v->{Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("image/*");startActivityForResult(pick,PICK_WORKER_PHOTO);});
  TextView nm=tv(name,22,true);nm.setTextColor(white);nm.setGravity(Gravity.CENTER);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,-2);np.topMargin=dp(8);card.addView(nm,np);
