  TextView details=tv("ADVISER ID   "+adviserId+"\n\nMOBILE   "+phone+"\nEMAIL   "+email+"\nSKILLS   "+skills+"\nSTATUS   "+status,13,false);details.setTextColor(white);details.setPadding(dp(4),dp(8),dp(4),dp(8));card.addView(details);
  TextView foot=tv("DIGITAL PROFILE ID • NOT A GOVERNMENT ID",9,true);foot.setTextColor(Color.rgb(255,174,75));foot.setGravity(Gravity.CENTER);card.addView(foot);
  content.addView(card,new LinearLayout.LayoutParams(-1,-2));
