  idPdfText="GIGSATHI ADVISER ID CARD\nName: "+shareName+"\nRole: Adviser\nAdviser ID: "+shareId+"\nMobile: "+sharePhone+"\nEmail: "+shareEmail+"\nSkills: "+shareSkills+"\nStatus: "+shareStatus+"\n\nDigital profile ID only; not a government identity document.";
